// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DEP_BANK, LogFile} from "../src/DEP_BANK.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    DEP_BANK c;
    LogFile log_;

    function setUp() public {
        c = new DEP_BANK();
        log_ = new LogFile();
    }

    function testFuzz_property(uint256 minSum, uint256 depositAmt, uint256 collectAmt, address actor) public {
        vm.assume(depositAmt <= VALUE_CAP);
        // keep actor non-zero and not the test contract
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));

        // MinSum below which we require the bug to be triggerable: choose a positive MinSum
        minSum = bound(minSum, 1, type(uint128).max);
        // deposit strictly below MinSum so the guard `balances[msg.sender] >= MinSum` must fail
        depositAmt = bound(depositAmt, 0, minSum - 1);
        // collect amount must be <= balance so that the mutant's `balances[msg.sender] >= _am` passes
        collectAmt = bound(collectAmt, 0, depositAmt);

        // Set up MinSum and LogFile before Initialized (guards unchanged by the mutant)
        c.SetMinSum(minSum);
        c.SetLogFile(address(log_));
        c.Initialized();

        // Deposit by actor
        vm.deal(actor, depositAmt);
        vm.prank(actor);
        c.Deposit{value: depositAmt}();

        // Record pre-collect balance and contract balance
        uint256 balBefore = c.balances(actor);
        uint256 contractBalBefore = address(c).balance;

        // Attempt Collect from actor with collectAmt <= balBefore < MinSum
        vm.prank(actor);
        bool ok;
        try c.Collect{value: 0}(collectAmt) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: if the guard `balance >= MinSum` fails (balance < MinSum), the reference must NOT
        // allow a successful Collect that reduces the balance or sends Ether out.  The mutant weakens the
        // guard to `balance >= 0`, so it can succeed and subtract _am, breaking the rule.
        bool invariantHolds;
        if (balBefore < minSum) {
            invariantHolds = !ok || (c.balances(actor) == balBefore && address(c).balance == contractBalBefore);
        } else {
            invariantHolds = true; // outside the targeted below-MinSum window
        }
        assertTrue(invariantHolds);
    }
}
